const urunler = [
  { ad: 'Kisirlastirilmis Somonlu Mama (15kg)', stok: 4500, tuketim: 85, planlanan: 2200, gerceklesen: 2450 },
  { ad: 'Bentonit Kedi Kumu (20L)', stok: 12000, tuketim: 400, planlanan: 750, gerceklesen: 680 },
  { ad: 'Odul & Vitamin', stok: 600, tuketim: 30, planlanan: 400, gerceklesen: 420 }
];

return urunler.map(u => {
  const kalanGun = Math.floor(u.stok / u.tuketim);
  const butceFarki = u.gerceklesen - u.planlanan;
  return {
    json: {
      urun: u.ad,
      kalanGun,
      butceFarki,
      uyariGerekli: kalanGun <= 15 || butceFarki > 0
    }
  };
});

